from math import log2, ceil
class Solution:
    def minDays(self, n: int) -> int:
        maxd = 2*ceil(log2(n))
        que = deque([(1,1)])
        seen = set()
        while que:
            v, d = que.popleft()
            seen.add(v)
            if v == n:
                return d
            for w in [v+1, 2*v, 3*v]:
                if w not in seen and d <= maxd and w <= n:
                    que.append((w,d+1))

class Solution:
    def minDays(self, n: int) -> int:
        result = 0
        q, lookup = [n], set([n])
        while q:
            new_q = []
            for i in q: 
                if not i:
                    return result
                if i-1 not in lookup:
                    lookup.add(i-1)
                    new_q.append(i-1)
                if i%2 == 0 and i//2 not in lookup:
                    lookup.add(i//2)
                    new_q.append(i//2)
                if i%3 == 0 and i//3 not in lookup:
                    lookup.add(i//3)
                    new_q.append(i//3)
            result += 1
            q = new_q
        return result

class Solution:
    def minDays(self, n: int) -> int:
        def memoization(lookup, i):
            if i <= 1:
                return i
            if i not in lookup:
                lookup[i] = 1+min(i%2+memoization(lookup, i//2),
                                  i%3+memoization(lookup, i//3))
            return lookup[i]

        lookup = {}
        return memoization(lookup, n)

class Solution(object):
    def thousandSeparator(self, n):
        n = str(n)
        if len(n) <= 3:
            return str(n)
        result = ""      
        dot = '.'
        index = 0
        startPos = len(n) % 3 
        if startPos == 0:
            startPos += 3
        val = -1
        while index < len(n):
            result += n[index]
            if index == startPos - 1:
                result += dot
                val = 0
            if val != -1:
                val += 1
                if val > 3 and (val - 1) % 3 == 0 and index != len(n) - 1:
                    result += dot
                    val = 1  
            index += 1

        return result

class Solution:
    def thousandSeparator(self, n):
        result = []
